import type { CynapContext } from '@cynap/sdk';

/** The record table and the fields the form may write. Replace both; keep the list equal to the Surface's. */
const RECORD_TABLE = 'REPLACE_WITH_RECORD_TABLE';
const EDITABLE_FIELDS = ['REPLACE_WITH_FIELD'];
/** The roles that may edit a record. */
const ALLOWED_ROLES = ['owner', 'admin'];

const asObj = (value: unknown): Record<string, unknown> | null =>
  typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as Record<string, unknown>) : null;

type SqlValue = string | number | boolean | null;
const isSqlValue = (value: unknown): value is SqlValue =>
  value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean';

export default async function handler(ctx: CynapContext): Promise<Record<string, unknown>> {
  const input = asObj(ctx.input) ?? {};
  // The viewer's identity is stamped by the platform from the signed-in session, never by the
  // Surface: a caller-supplied portal_actor is refused before the run starts. Fail closed without it.
  const actor = asObj(input.portal_actor);
  const role = actor && typeof actor.role === 'string' ? actor.role : null;
  if (role === null || !ALLOWED_ROLES.includes(role)) {
    return { success: false, error: 'not_permitted', rowsAffected: 0 };
  }

  const recordId = typeof input.record_id === 'string' ? input.record_id : '';
  const values = asObj(input.values) ?? {};
  // Only the allowed fields, and only scalar values: anything else the Surface sent is ignored.
  const fields = EDITABLE_FIELDS.filter((name) => Object.hasOwn(values, name) && isSqlValue(values[name]));
  if (recordId === '' || fields.length === 0) {
    return { success: false, error: 'invalid_input', rowsAffected: 0 };
  }

  // Field-scoped: the row's other columns are never rewritten from what the Surface read.
  const result = asObj(
    await ctx.tools.knowledge.executeSql(
      `UPDATE ${RECORD_TABLE} SET ${fields.map((name) => `${name} = ?`).join(', ')} WHERE id = ?`,
      [...fields.map((name) => values[name] as SqlValue), recordId]
    )
  );
  const rowsAffected = typeof result?.rowsAffected === 'number' ? result.rowsAffected : 0;
  await ctx.log.info('record_form_save', { fields: fields.length, rowsAffected });
  return { ok: true, rowsAffected };
}

